from fractions import Fraction


class Group:
    def __init__(self, members: list[str]) -> None:
        self._balances = dict.fromkeys(members, Fraction(0))

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        participants = list(self._balances) if participants is None else participants
        if not participants:
            raise ValueError("An expense must have at least one participant")
        if any(participant not in self._balances for participant in participants):
            raise ValueError("Participant is not a group member")

        try:
            amount_fraction = Fraction(str(amount))
        except (ValueError, ZeroDivisionError) as exc:
            raise ValueError("Amount must be a finite positive number") from exc
        if amount_fraction <= 0:
            raise ValueError("Amount must be positive")

        share = amount_fraction / len(participants)
        self._balances[payer] += amount_fraction
        for participant in participants:
            self._balances[participant] -= share

    def balances(self) -> dict[str, float]:
        return {member: float(balance) for member, balance in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = [
            [member, -balance]
            for member, balance in self._balances.items()
            if balance <= -1
        ]
        creditors = [
            [member, balance]
            for member, balance in self._balances.items()
            if balance >= 1
        ]

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            amount = min(debtors[i][1], creditors[j][1])
            payments.append((debtors[i][0], creditors[j][0], float(amount)))
            debtors[i][1] -= amount
            creditors[j][1] -= amount

            if debtors[i][1] < 1:
                i += 1
            if creditors[j][1] < 1:
                j += 1

        return payments
